from math import comb

def R_Kn(n):
    if n < 4:
        return 0.0 # Or handle error, but we check n >= 4
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)
    if f_kn == 0:
        return 0.0
    return (g_kn**3) / (f_kn**4)

# Test small values to confirm monotonicity trend
n_values = range(4, 10)
results = {n: R_Kn(n) for n in n_values}

print("R(K_n) for n=4 to 9:")
for n, r in results.items():
    print(f"n={n}: {r}")

# Verify the analytical form: R(K_n) = (3/32) * (n-3)^3 / (n(n-1)(n-2))
def R_Kn_analytic(n):
    if n < 4:
        return 0.0
    return (3/32) * ((n-3)**3) / (n * (n-1) * (n-2))

print("\nVerification of analytic formula for n=9:")
print(f"Numerical: {R_Kn(9)}")
print(f"Analytic: {R_Kn_analytic(9)}")

# Verify strict increase: R(K_{n+1}) / R(K_n) > 1 for n >= 4
def ratio_check(n):
    if n < 4:
        return 0.0
    return R_Kn(n+1) / R_Kn(n)

# Check the ratio for a few values
n_check = [4, 5, 6]
print("\nRatio R(K_{n+1}) / R(K_n) for n=4, 5, 6:")
for n in n_check:
    print(f"n={n}: {ratio_check(n)}")

